package com.smartcanteen.controller;
import com.smartcanteen.entity.*;import com.smartcanteen.repository.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.web.bind.annotation.*;import java.math.BigDecimal;import java.util.*;
@RestController public class MenuController {private final FoodItemRepository foods;private final CategoryRepository cats;public MenuController(FoodItemRepository f,CategoryRepository c){foods=f;cats=c;}
public record FoodRequest(@NotBlank String name,String description,@NotNull @DecimalMin("0.01") BigDecimal price,String imageUrl,@NotNull Long categoryId,Boolean available){} public record CategoryRequest(@NotBlank String name,String description){}
@GetMapping("/api/categories") public List<Category> categories(){return cats.findAll().stream().filter(Category::isActive).toList();}
@GetMapping("/api/food-items") public List<FoodItem> list(@RequestParam(required=false)Long categoryId,@RequestParam(required=false)String search){if(search!=null&&!search.isBlank())return foods.findByNameContainingIgnoreCaseAndAvailableTrue(search.trim());if(categoryId!=null)return foods.findByCategoryIdAndAvailableTrueOrderByNameAsc(categoryId);return foods.findByAvailableTrueOrderByNameAsc();}
@GetMapping("/api/food-items/{id}") public FoodItem get(@PathVariable Long id){return foods.findById(id).orElseThrow(()->new IllegalArgumentException("Food item not found."));}
@PostMapping("/api/admin/food-items") public FoodItem create(@Valid @RequestBody FoodRequest r){FoodItem f=new FoodItem();return save(f,r);}
@PutMapping("/api/admin/food-items/{id}") public FoodItem update(@PathVariable Long id,@Valid @RequestBody FoodRequest r){return save(foods.findById(id).orElseThrow(()->new IllegalArgumentException("Food item not found.")),r);}
private FoodItem save(FoodItem f,FoodRequest r){f.setName(r.name().trim());f.setDescription(r.description());f.setPrice(r.price());f.setImageUrl(r.imageUrl());f.setCategory(cats.findById(r.categoryId()).orElseThrow(()->new IllegalArgumentException("Category not found.")));if(r.available()!=null)f.setAvailable(r.available());return foods.save(f);}
@PatchMapping("/api/admin/food-items/{id}/availability") public FoodItem availability(@PathVariable Long id,@RequestBody Map<String,Boolean> b){FoodItem f=foods.findById(id).orElseThrow();f.setAvailable(Boolean.TRUE.equals(b.get("available")));return foods.save(f);}
@DeleteMapping("/api/admin/food-items/{id}") public Map<String,String> delete(@PathVariable Long id){FoodItem f=foods.findById(id).orElseThrow();f.setAvailable(false);foods.save(f);return Map.of("message","Food item deactivated.");}
@PostMapping("/api/admin/categories") public Category addCategory(@Valid @RequestBody CategoryRequest r){Category c=new Category();c.setName(r.name().trim());c.setDescription(r.description());return cats.save(c);}
@PutMapping("/api/admin/categories/{id}") public Category updateCategory(@PathVariable Long id,@Valid @RequestBody CategoryRequest r){Category c=cats.findById(id).orElseThrow();c.setName(r.name().trim());c.setDescription(r.description());return cats.save(c);}}
